-- Q1 [pKa & Protonation States] easy skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'pKa & Protonation States', 'A solution of free cysteine is titrated, and a chemist tracks the thiol (\(-\text{SH}\)) side chain, which has a \(\text{pK}_a\) of about \(8.3\). At what solution \(\text{pH}\) are exactly half of the thiol groups present in their deprotonated (\(-\text{S}^-\)) form?', '[{"label": "A", "text": "At a \\(\\text{pH}\\) of \\(8.3\\)"}, {"label": "B", "text": "At a \\(\\text{pH}\\) about \\(2\\) units below \\(8.3\\)"}, {"label": "C", "text": "At a \\(\\text{pH}\\) about \\(2\\) units above \\(8.3\\)"}, {"label": "D", "text": "At a \\(\\text{pH}\\) of \\(7.0\\)"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because the \(\text{pK}_a\) of an ionizable group is, by definition, the \(\text{pH}\) at which that group is exactly half deprotonated. LibreTexts states this directly: "If the \(\text{pH} = \text{pK}_a\) ... the functional group will be 50% deprotonated," because the Henderson-Hasselbalch equation reduces to \(0 = \log([\text{A}^-]/[\text{HA}])\), giving \([\text{A}^-] = [\text{HA}]\) (a 50/50 mixture). Since the thiol''s \(\text{pK}_a\) is \(8.3\), the half-deprotonated point is exactly \(\text{pH} = 8.3\). (Choice A) is correct: setting \(\text{pH}\) equal to the \(\text{pK}_a\) of \(8.3\) makes \([-\text{S}^-] = [-\text{SH}]\), the 50% deprotonated condition. (Choice B) is wrong because \(2\) units below the \(\text{pK}_a\) the group is about 99% protonated, not half deprotonated — that is the "fully protonated" extreme, not the midpoint. (Choice C) is wrong because \(2\) units above the \(\text{pK}_a\) the group is about 99% deprotonated, the opposite extreme from half. (Choice D) is wrong because \(\text{pH} = 7.0\) is below the \(\text{pK}_a\) of \(8.3\), so the thiol is mostly protonated; \(7.0\) is the neutral point of pure water, which is unrelated to this group''s \(\text{pK}_a\). This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between \(\text{pH}\) and \(\text{pK}_a\) to identify the half-deprotonation point for a specific side chain.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 75)
  RETURNING id
)
