-- Q6 [pKa & Protonation States] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'pKa & Protonation States', 'A biochemist tabulates the side-chain \(\text{pK}_a\) values for three residues she is studying: cysteine (thiol), tyrosine (phenol), and arginine (guanidinium). Working only from the chemistry of these groups, she ranks the side chains from the one that loses its side-chain proton at the LOWEST \(\text{pH}\) to the one that loses it at the HIGHEST \(\text{pH}\). Which ranking, lowest \(\text{pK}_a\) to highest, does she record?

| Residue | Side-chain group |
|---|---|
| Cysteine | thiol \((-\text{SH})\) |
| Tyrosine | phenol \((-\text{OH})\) |
| Arginine | guanidinium \((-\text{NH}^+)\) |', '[{"label": "A", "text": "Tyrosine < Cysteine < Arginine"}, {"label": "B", "text": "Cysteine < Tyrosine < Arginine"}, {"label": "C", "text": "Arginine < Tyrosine < Cysteine"}, {"label": "D", "text": "Cysteine < Arginine < Tyrosine"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because the side-chain \(\text{pK}_a\) reports the \(\text{pH}\) at which a group is half-deprotonated, so a group that gives up its proton at a lower \(\text{pH}\) has the lower \(\text{pK}_a\). The textbook lists the three side-chain \(\text{pK}_a\) values together as cysteine thiol \((\text{pK}_a = 8.37)\), tyrosine phenol \((\text{pK}_a = 10.46)\), and arginine guanidinium \((\text{pK}_a = 12.48)\), so the thiol is the most acidic, the phenol is intermediate, and the guanidinium holds its proton most tightly. Ordering lowest to highest therefore gives cysteine \((8.37)\) < tyrosine \((10.46)\) < arginine \((12.48)\). (Choice A) inverts cysteine and tyrosine, placing the phenol below the thiol, which contradicts the thiol \((8.37)\) being more acidic than the phenol \((10.46)\). (Choice B) is correct: it orders thiol < phenol < guanidinium, exactly tracking \(8.37 < 10.46 < 12.48\). (Choice C) is the full reverse ranking (highest to lowest), which would answer ''most acidic last'' rather than first. (Choice D) keeps cysteine lowest but swaps tyrosine and arginine, putting the guanidinium \((12.48)\) below the phenol \((10.46)\) even though guanidinium is the least acidic of the three. This is a Scientific Reasoning and Problem Solving question because you must apply the meaning of \(\text{pK}_a\) to rank ionizable side chains by acidity.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
