-- Q9 [Zwitterions & Titration Curves] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Zwitterions & Titration Curves', 'An amino acid with a non-ionizable side chain is dissolved near neutral \(\text{pH}\), where it exists predominantly as a zwitterion with a net charge of zero. A student reasons that "net zero" describes the molecule''s overall charge but may not describe its individual groups. Which charge configuration on the \(\alpha\)-groups most likely accounts for this net-zero zwitterion?', '[{"label": "A", "text": "No charge on either \\(\\alpha\\)-group"}, {"label": "B", "text": "A single \\(+1\\) charge overall"}, {"label": "C", "text": "A single \\(-1\\) charge overall"}, {"label": "D", "text": "Both a \\(+1\\) and a \\(-1\\) charge"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because a zwitterion is a dipolar ion: its net charge is zero, but that zero arises from a full positive and a full negative charge that coexist on the molecule, not from the absence of charge. The LibreTexts text states that "when protonated, the amino group carries a +1 charge," and that "when deprotonated... the carboxyl group carries a -1 charge." Near neutral pH the \(\alpha\)-carboxyl (\(\text{pK}_a \approx 2\)) is deprotonated to \(-\text{COO}^-\) (charge \(-1\)) while the \(\alpha\)-amino (\(\text{pK}_a \approx 9{-}10\)) stays protonated as \(-\text{NH}_3^+\) (charge \(+1\)); the side chain contributes nothing, so the two opposite charges sum to a net of zero. (Choice A) is wrong: a molecule with no charge on either \(\alpha\)-group is not a zwitterion, and at neutral pH the carboxyl is deprotonated (\(-1\)) and the amino group protonated (\(+1\)) rather than both neutral. (Choice B) is wrong: a single net \(+1\) charge describes the fully protonated cation that dominates only at very low pH, not the net-neutral zwitterion. (Choice C) is wrong: a single net \(-1\) charge describes the anion that dominates only at high pH, after the \(\alpha\)-amino group has been deprotonated. (Choice D) is correct: the simultaneous \(+1\) on \(-\text{NH}_3^+\) and \(-1\) on \(-\text{COO}^-\) is exactly what makes the species a net-zero dipolar zwitterion. This is a Knowledge of Scientific Concepts and Principles question because you must recall that a zwitterion carries equal and opposite charges that sum to a net of zero.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 70)
  RETURNING id
)
