-- Q10 [pKa & Protonation States] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'pKa & Protonation States', 'A biochemist studying the active site of an mRNA-capping enzyme finds that an active-site tyrosine, whose phenolic side chain has a \(\text{pK}_a\) of 10.1, is functioning as a general acid. Under the local conditions, the side chain is measured to be 75% deprotonated (ionized). Applying the Henderson-Hasselbalch equation, the local \(\text{pH}\) is most likely closest to which value?', '[{"label": "A", "text": "Approximately 9.62"}, {"label": "B", "text": "Approximately 10.58"}, {"label": "C", "text": "Approximately 10.10"}, {"label": "D", "text": "Approximately 9.98"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because the Henderson-Hasselbalch equation, \(\text{pH} = \text{pK}_a + \log\left(\frac{[\text{A}^-]}{[\text{HA}]}\right)\), relates pH to the ratio of deprotonated to protonated side chain. LibreTexts writes this form explicitly as "pH = pKa + log [A]/[HA]" (line 5536). A side chain that is 75% deprotonated has \([\text{A}^-]/[\text{HA}] = 75/25 = 3\), and \(\log(3) = 0.477\), so \(\text{pH} = 10.1 + 0.477 \approx 10.58\). This reproduces the textbook worked example, which uses an active-site tyrosine that is "75% ionized" and computes "pH = 10.1 + (0.477)" giving "pH = 10.58" (lines 4867-4880); the same passage notes that tyrosine''s R-group "can act as either an acid or base" (lines 4864-4865). Because the side chain is more than half deprotonated, the pH must lie above the \(\text{pK}_a\) of 10.1. (Choice A) Approximately 9.62 results from subtracting the log term instead of adding it (\(10.1 - 0.477\)), or equivalently from inverting the ratio to \(25/75\); this places the pH below the \(\text{pK}_a\), which would predict a majority-protonated side chain, contradicting the 75%-ionized datum (LibreTexts 5505-5510). (Choice B) is correct: adding \(\log(3) = 0.477\) to the \(\text{pK}_a\) of 10.1 gives \(\text{pH} \approx 10.58\), matching the textbook calculation (lines 4879-4880, 5536). (Choice C) Approximately 10.10 is simply the \(\text{pK}_a\); this answer ignores the 75% datum and treats the residue as 50% ionized, but pH equals \(\text{pK}_a\) only at half-dissociation, where \([\text{A}^-]=[\text{HA}]\) (lines 5509-5510). (Choice D) Approximately 9.98 comes from plugging "75%" in as the ratio itself (\(\log 0.75 = -0.125\), giving \(10.1 - 0.125\)) rather than forming the correct \([\text{A}^-]/[\text{HA}] = 75/25 = 3\); the equation requires the ratio of the two species, not the lone percentage (line 5536). This is a Scientific Reasoning and Problem Solving question because you must apply the Henderson-Hasselbalch equation to a described situation, convert a percent-ionized value into the correct concentration ratio, and solve for pH.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 120)
  RETURNING id
)
