-- Q17 [Isoelectric Point (pI)] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Isoelectric Point (pI)', 'A student titrates a solution of free serine, whose polar side chain stays uncharged across the titration, and wants to calculate its isoelectric point \(\text{pI}\). To find the \(\text{pH}\) at which serine exists predominantly as the net-neutral zwitterion, the two \(\text{pK}_a\) values she should average are those of the:', '[{"label": "A", "text": "side-chain hydroxyl and \\(\\alpha\\)-amino groups"}, {"label": "B", "text": "side-chain hydroxyl and \\(\\alpha\\)-carboxyl groups"}, {"label": "C", "text": "\\(\\alpha\\)-carboxyl and \\(\\alpha\\)-amino groups"}, {"label": "D", "text": "all three ionizable groups, averaged equally"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because the \(\text{pI}\) is found by averaging the \(\text{pK}_a\) values of the two groups that flank the net-neutral (zwitterionic) species on either side. The textbook states the \(\text{pI}\) "can be determined by averaging the \(\text{pK}_a\) values of the two groups closest to and on either side of the \(\text{pI}\)" (LibreTexts 5564-5565). For serine the side chain is an alcohol that carries zero charge when protonated (line 5486) and has a \(\text{pK}_a \approx 13\) (line 5601), so it stays uncharged across the titration; the only two groups that gain or lose charge are the \(\alpha\)-carboxyl (\(-\text{COO}^-\), \(\text{pK}_a \approx 2.2\)) and the \(\alpha\)-amino (\(-\text{NH}_3^+\), \(\text{pK}_a \approx 9.2\)); the zwitterion sits between them, giving \(\text{pI} = (2.2 + 9.2)/2 \approx 5.7\). (Choice A) is incorrect: the side-chain hydroxyl does not ionize in this range, so it is not one of the groups flanking the zwitterion; pairing it with the \(\alpha\)-amino group leaves out the \(\alpha\)-carboxyl that actually borders the neutral form. (Choice B) is incorrect for the same reason in reverse: it substitutes the non-ionizing hydroxyl for the \(\alpha\)-amino group, ignoring that serine''s neutral form is bounded below by \(-\text{COO}^-\) and above by \(-\text{NH}_3^+\). (Choice C) is correct: averaging the \(\alpha\)-carboxyl and \(\alpha\)-amino \(\text{pK}_a\) values gives the \(\text{pH}\) where serine carries no net charge. (Choice D) is incorrect because serine has only two groups that change charge in this range; treating it as if three groups must be averaged misapplies the rule used for amino acids with an ionizable side chain. This is a Knowledge of Scientific Concepts and Principles question because you must recall that the \(\text{pI}\) of a neutral amino acid is the average of the \(\text{pK}_a\) values of the two groups flanking the zwitterion.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
