-- Q19 [Isoelectric Point (pI)] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Isoelectric Point (pI)', 'A student is calculating the isoelectric point of arginine, whose three ionizable groups have approximate \(\text{pK}_a\) values of \(2.0\) (\(\alpha\text{-}\text{COOH}\)), \(9.0\) (\(\alpha\text{-}\text{NH}_3^+\)), and \(12.5\) (guanidinium side chain). To find the \(\text{pI}\), she must average the two \(\text{pK}_a\) values that flank the net-neutral form. Which \(\text{pI}\) does she obtain?', '[{"label": "A", "text": "\\(5.5\\)"}, {"label": "B", "text": "\\(10.75\\)"}, {"label": "C", "text": "\\(7.25\\)"}, {"label": "D", "text": "\\(7.8\\)"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because the textbook states that the \(\text{pI}\) is found by averaging the \(\text{pK}_a\) values of the two groups closest to and on either side of the net-neutral species. Arginine is basic, so as pH rises the \(\alpha\text{-}\text{COOH}\) (\(\text{pK}_a\) \(2.0\)) loses its proton first, taking the molecule from \(+2\) to a still-positive \(+1\); the molecule only reaches net zero after the \(\alpha\text{-}\text{NH}_3^+\) (\(\text{pK}_a\) \(9.0\)) deprotonates, and the very last group to leave is the guanidinium side chain (\(\text{pK}_a\) \(12.5\)). The net-neutral zwitterion is therefore flanked by the two HIGHEST \(\text{pK}_a\) values, so \(\text{pI} = (9.0 + 12.5)/2 = 10.75\). (Choice A) \(5.5\) averages the two LOWEST \(\text{pK}_a\) (\((2.0 + 9.0)/2\)) — that is the formula for a neutral amino acid, but arginine''s basic side chain means the neutral form sits higher, between \(9.0\) and \(12.5\). (Choice B) is correct: averaging the two \(\text{pK}_a\) flanking the net-neutral form, \((9.0 + 12.5)/2 = 10.75\). (Choice C) \(7.25\) averages the lowest and highest \(\text{pK}_a\) (\((2.0 + 12.5)/2\)), skipping the middle group, so it does not bracket the neutral species. (Choice D) \(7.8\) averages all three \(\text{pK}_a\) (\((2.0 + 9.0 + 12.5)/3\)) instead of only the two that flank net neutrality. This is a Scientific Reasoning and Problem Solving question because you must apply the rule that \(\text{pI}\) is the average of the two \(\text{pK}_a\) bracketing the net-neutral form to a specific basic amino acid and select the correct pair.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 110)
  RETURNING id
)
