-- Q20 [Isoelectric Point (pI)] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Isoelectric Point (pI)', 'A student titrates free arginine and records three \(\text{pK}_a\) values: \(\alpha\text{-COOH} = 2.0\), \(\alpha\text{-}\text{NH}_3^+ = 9.0\), and the guanidinium side chain \(= 12.5\). Reasoning that the net-neutral (zwitterionic) species is flanked by the two \(\text{pK}_a\) values on either side of it, what \(\text{pI}\) should the student calculate?', '[{"label": "A", "text": "\\(\\text{pI} \\approx 5.5\\)"}, {"label": "B", "text": "\\(\\text{pI} \\approx 7.3\\)"}, {"label": "C", "text": "\\(\\text{pI} \\approx 12.5\\)"}, {"label": "D", "text": "\\(\\text{pI} \\approx 10.8\\)"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because the \(\text{pI}\) is found by averaging the two \(\text{pK}_a\) values that flank the net-neutral species. Arginine is a basic amino acid with three ionizable groups (\(\alpha\text{-COOH} = 2.0\), \(\alpha\text{-}\text{NH}_3^+ = 9.0\), guanidinium \(= 12.5\)); as pH rises the \(\alpha\text{-COOH}\) deprotonates first (giving the net-neutral zwitterion), and the next group to lose a proton is the \(\alpha\text{-}\text{NH}_3^+\). The textbook states the \(\text{pI}\) is found by "averaging the pKa values of the two groups closest to and on either side of the pI," so for this basic residue you average \(\alpha\text{-}\text{NH}_3^+\) and the guanidinium side chain: \(\text{pI} = (9.0 + 12.5)/2 = 10.75 \approx 10.8\). (Choice A) is incorrect because \(\text{pI} \approx 5.5\) comes from averaging the two lowest \(\text{pK}_a\) values, \((2.0 + 9.0)/2\) — the pair that flanks the neutral species of a residue WITHOUT a basic side chain, not arginine. (Choice B) is incorrect because \(\text{pI} \approx 7.3\) comes from averaging the extreme \(\text{pK}_a\) values, \((2.0 + 12.5)/2\), which skips over the central \(\alpha\text{-}\text{NH}_3^+\) group rather than using the two that actually straddle the zwitterion. (Choice C) is incorrect because \(\text{pI} \approx 12.5\) simply reports the guanidinium \(\text{pK}_a\) alone without averaging it with the adjacent group, ignoring that a \(\text{pI}\) is always a midpoint between two \(\text{pK}_a\) values. (Choice D) is correct: averaging the \(\alpha\text{-}\text{NH}_3^+\) (9.0) and guanidinium (12.5) \(\text{pK}_a\) values gives \(\text{pI} \approx 10.8\), consistent with arginine being a strongly basic amino acid. This is a Scientific Reasoning and Problem Solving question because you must apply the pI-averaging rule to a specific pKa set, identify which two of three pKa values flank the net-neutral species, and compute the result.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
