WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Isoelectric Point (pI)', 'A student calculates the isoelectric point of free tyrosine, whose three ionizable groups have the following \(\text{pK}_a\) values: \(\alpha\text{-COOH} = 2.2\), \(\alpha\text{-NH}_3^+ = 9.1\), and the phenol side chain \(= 10.5\). Because the phenol group does not flank the net-neutral (zwitterionic) species, which value should the student obtain for the \(\text{pI}\)?', '[{"label": "A", "text": "9.80"}, {"label": "B", "text": "6.35"}, {"label": "C", "text": "7.27"}, {"label": "D", "text": "5.65"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because the \(\text{pI}\) is found by averaging the \(\text{pK}_a\) values of the two groups that straddle the net-neutral species, and for tyrosine those are the \(\alpha\text{-COOH}\) and \(\alpha\text{-NH}_3^+\), not the phenol. As the textbook states, the \(\text{pI}\) is determined "by averaging the pKa values of the two groups closest to and on either side of the pI"; for vasopressin the source likewise instructs you to "determine which two pKa values are the closest and straddle the pH at which the molecule has a net neutral charge." Tyrosine''s phenol side chain (\(\text{pK}_a \approx 10.5\)) is uncharged when protonated and only deprotonates to \(-1\) at high pH, so it lies above both backbone groups and cannot flank the zwitterion. Working from the bottom up: below \(\text{pH} = 2.2\) the charge is \(+1\); between \(2.2\) and \(9.1\) the \(\alpha\text{-COO}^-\) (\(-1\)) cancels the \(\alpha\text{-NH}_3^+\) (\(+1\)) for net zero; the phenol stays neutral throughout this window. Thus \(\text{pI} = (2.2 + 9.1)/2 = 5.65\). (Choice A) is 9.80, the result of averaging \(\alpha\text{-NH}_3^+\) and the phenol \((9.1 + 10.5)/2\) as if tyrosine were a basic amino acid. (Choice B) is 6.35, from averaging \(\alpha\text{-COOH}\) and the phenol \((2.2 + 10.5)/2\), wrongly treating the phenol as if it flanked the neutral form like the acidic side chain of Asp/Glu. (Choice C) is 7.27, the average of all three \(\text{pK}_a\) values \((2.2 + 9.1 + 10.5)/3\) instead of only the two flanking groups. (Choice D) is correct: averaging only the \(\alpha\text{-COOH}\) and \(\alpha\text{-NH}_3^+\) that bound the zwitterion gives \((2.2 + 9.1)/2 = 5.65\). This is a Scientific Reasoning and Problem Solving question because you must apply the rule for which two \(\text{pK}_a\) flank the net-neutral form to a specific residue and compute the \(\text{pI}\).', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'basic-AA rule misapplied to an acidic (phenolic) side chain' FROM q
  UNION ALL
  SELECT id, 'B', 'partial_truth', 'acidic-AA rule misapplied; phenol treated as flanking the zwitterion' FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', 'averaged all ionizable pKa instead of the two flanking ones' FROM q;

-- Q25 [Isoelectric Point (pI)] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Isoelectric Point (pI)', 'A student titrates free threonine in water and records the table of \(\text{pK}_a\) values shown. Threonine is a polar-uncharged amino acid whose \(\beta\)-hydroxyl side chain does not ionize over the accessible \(\text{pH}\) range. Using the two flanking \(\text{pK}_a\) values, the student calculates the \(\text{pI}\) of threonine.

| Ionizable group | \(\text{pK}_a\) |
|---|---|
| \(\alpha\text{-}\text{COOH}\) | 2.1 |
| \(\beta\text{-OH (side chain)}\) | does not ionize |
| \(\alpha\text{-}\text{NH}_3^+\) | 9.1 |

What \(\text{pI}\) should the student obtain?', '[{"label": "A", "text": "\\(\\text{pI} = 9.80\\)"}, {"label": "B", "text": "\\(\\text{pI} = 8.07\\)"}, {"label": "C", "text": "\\(\\text{pI} = 5.60\\)"}, {"label": "D", "text": "\\(\\text{pI} = 7.40\\)"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because the \(\text{pI}\) is found by "averaging the pKa values of the two groups closest to and on either side of the pI," and you only count groups that can contribute to a charge on the molecule. Threonine is a polar-uncharged amino acid: its \(\beta\)-hydroxyl side chain does not ionize over the accessible \(\text{pH}\) range (the textbook even lists \(-\text{OH}\) groups like serine''s with \(\text{pK}_a \approx 13\)), so the only ionizable groups are the \(\alpha\text{-}\text{COOH}\) (\(\text{pK}_a = 2.1\)) and \(\alpha\text{-}\text{NH}_3^+\) (\(\text{pK}_a = 9.1\)). Between these two \(\text{pK}_a\), threonine exists as the net-neutral zwitterion, so \(\text{pI} = (2.1 + 9.1)/2 = 11.2/2 = 5.60\). (Choice A) \(\text{pI} = 9.80\) treats the non-ionizing \(\beta\)-hydroxyl as an ionizable group with a phenol-like \(\text{pK}_a \approx 10.5\) and averages the two highest values, \((9.1 + 10.5)/2\) — but the textbook lists serine and threonine hydroxyls as polar-uncharged groups with no charge-bearing side-chain \(\text{pK}_a\), unlike the ionizing acidic and basic side chains. (Choice B) \(\text{pI} = 8.07\) averages all three "groups" including a non-ionizing \(-\text{OH}\) counted as \(\text{pK}_a \approx 13\), \((2.1 + 9.1 + 13)/3\); the \(\text{pI}\) is the average of only the two \(\text{pK}_a\) that flank the zwitterion, never the mean of every group. (Choice C) is correct: averaging only the two backbone \(\text{pK}_a\) that straddle the net-neutral species gives \((2.1 + 9.1)/2 = 5.60\). (Choice D) \(\text{pI} = 7.40\) mistakes physiological \(\text{pH} = 7.4\) for the \(\text{pI}\); although the zwitterion is the dominant net-neutral form near physiological pH, the \(\text{pI}\) is set by the residue''s own flanking \(\text{pK}_a\), not by physiological pH. This is a Scientific Reasoning and Problem Solving question because you must apply the pI-averaging rule and the ionizable-group classification to a \(\text{pK}_a\) table to compute the correct value.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', NULL FROM q
  UNION ALL
  SELECT id, 'B', 'process_step_confusion', NULL FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', NULL FROM q;
